#include <stdlib.h>
#include <omp.h>

#define BLOCK_SIZE 1024

void prefix_sum_parallel(int* a, size_t n, size_t block_size) {
    int num_blocks = (n + block_size - 1) / block_size;
    int *flag = (int *)malloc(num_blocks * sizeof(int));
    memset(flag, 0, num_blocks * sizeof(int));

    double start_time = omp_get_wtime();
    #pragma omp parallel for schedule(static)
    for (int i = 0; i < num_blocks; i++) {
        int start = i * block_size;
        int end = std::min(start + block_size, n);

        // Wait for all previous blocks to finish
        for (int j = 0; j < i; j++) {
            while (!flag[j]) {
