        }

        // Perform prefix sum within this block
        int sum = 0;
        for (int k = start; k < end; k++) {
            sum += a[k];
        }

        // Update the array with the accumulated sum
        for (int k = start; k < end; k++) {
            a[k] = sum;
        }

        // Set the flag for the next block
        flag[i] = 1;
